// Synthetic credentials, local temporary metadata, fake HTTP and fake Keychain.
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import '../lib/source_digest.dart';
import '../lib/minimax_accounts.dart';
import '../lib/minimax_http.dart';
import 'synthetic_fixture.dart' show MiniMaxRegion;
import 'synthetic_fixture.dart' as fixture;

Map<String,dynamic> panel({bool today=true,int status=2})=>{'scene':1,'days':[for(var i=1;i<=7;i++){'day_no':i,'points':10,'status':i==1?status:1,'is_today':i==1&&today}]};
MiniMaxReply response(Map<String,dynamic> data)=>MiniMaxReply(200,{'base_resp':{'status_code':0},'data':data});
class FakeHttp extends MiniMaxHttp {
 final calls=<MiniMaxEndpoint>[];
 MiniMaxReply profile=const MiniMaxReply(200,{'statusInfo':{'code':0},'data':{'userInfo':{'realUserID':'server-user','name':'Synthetic'}}});
 MiniMaxReply status=response(panel());
 MiniMaxReply receipt=response({'claim_id':'synthetic-receipt','claim_result':1,'day_no':1,'points':10,'expire_at_ms':999999,'panel':panel(status:3)});
 bool loseClaim=false;Future<void> Function(MiniMaxEndpoint)? pause;
 @override Future<MiniMaxReply> send(MiniMaxEndpoint e,{required String accessToken,required String region,String? userId,bool Function()? isCurrent})async{
  if(accessToken!='synthetic-access'&&accessToken!='synthetic-new')throw StateError('wrong token');
  await pause?.call(e);if(!(isCurrent?.call()??true))throw StateError('request_cancelled');calls.add(e);
  if(e==MiniMaxEndpoint.claim&&loseClaim)throw StateError('synthetic private transport detail');
  return e==MiniMaxEndpoint.profile?profile:e==MiniMaxEndpoint.status?status:receipt;
 }
}
void expect(bool v,String s){if(!v)throw StateError(s);}
Future<void> reject(Future<Object?> Function() f,[String? code])async{try{await f();}on MiniMaxAccountError catch(e){expect(code==null||e.code==code,'wrong error ${e.code}');return;}throw StateError('accepted');}
Future<void> main()async{
 var passed=0,failed=0;
 final root=await Directory('loongpass-minimax-actions-20261104/evidence').createTemp('actions-synthetic-');
 var index=0; var time=100000;
 Future<void> check(String name,Future<void> Function(Directory) body)async{final d=await root.createTemp('${index++}-');await Process.run('/bin/chmod',['700',d.path]);try{await body(d);passed++;stdout.writeln('PASS $name');}catch(e){failed++;stdout.writeln('FAIL $name: $e');}finally{time=100000;}}
 final secrets=<String,String>{};
 Future<MiniMaxCredential> read()=>Future.value(MiniMaxCredential.parse(fixture.bytes(),sourcePath:fixture.path(MiniMaxRegion.cn),region:'cn',nowMs:time));
 MiniMaxAccounts service(Directory d,FakeHttp h,{Future<void> Function()? sync})=>MiniMaxAccounts(store:MiniMaxMetadataStore(d,syncDirectory:sync??()async{}),readSecret:(id)async=>secrets[id],writeSecret:(id,token)async{secrets[id]=token;},deleteSecret:(id)async{secrets.remove(id);},http:h,nowMs:()=>time);
 Future<MiniMaxAccount> imported(MiniMaxAccounts s)async=>s.save(await s.verifySource(read,confirmed:true),confirmed:true);
 await check('verify then save uses server identity and token only Keychain', (d)async{final h=FakeHttp();final s=service(d,h);final a=await imported(s);expect(a.uid=='server-user','local subject trusted');expect(h.calls.length==1&&h.calls.single==MiniMaxEndpoint.profile,'profile verification missing');final files=await d.list().where((f)=>f is File&&f.path.endsWith('.json')).toList();expect(files.length==1,'metadata missing');final raw=await File(files.single.path).readAsString();expect(!raw.contains('synthetic-access')&&!raw.contains('synthetic-refresh'),'credential in metadata');expect(!jsonEncode(a.toJson()).contains('synthetic-access'),'DTO credential leak');expect((await s.list()).length==1,'not saved');s.dispose();});
 await check('read/verify and save separately require confirmation', (d)async{final h=FakeHttp();final s=service(d,h);await reject(()=>s.verifySource(read,confirmed:false),'ConfirmationRequired');expect(h.calls.isEmpty,'unconfirmed HTTP');final v=await s.verifySource(read,confirmed:true);await reject(()=>s.save(v,confirmed:false),'ConfirmationRequired');expect((await s.list()).isEmpty,'unconfirmed save');s.dispose();});
 await check('bad profile cannot become account', (d)async{final h=FakeHttp()..profile=const MiniMaxReply(401,null);final s=service(d,h);await reject(()=>s.verifySource(read,confirmed:true),'NeedsLogin');expect((await s.list()).isEmpty,'bad profile saved');s.dispose();});
 await check('source replacement before save is rejected', (d)async{final h=FakeHttp();final s=service(d,h);var changed=false;Future<MiniMaxCredential> source()async=>MiniMaxCredential.parse(fixture.bytes(row:fixture.record()..['generation']=(changed?10:9)),sourcePath:fixture.path(MiniMaxRegion.cn),region:'cn',nowMs:time);final v=await s.verifySource(source,confirmed:true);changed=true;await reject(()=>s.save(v,confirmed:true),'SourceChanged');s.dispose();});
 await check('saved import cannot be replayed', (d)async{final s=service(d,FakeHttp());final v=await s.verifySource(read,confirmed:true);await s.save(v,confirmed:true);await reject(()=>s.save(v,confirmed:true),'ImportCompleted');s.dispose();});
 await check('claim records real receipt and same-day never sends twice', (d)async{final h=FakeHttp();final s=service(d,h);s.dispose();final live=service(d,h);final a=await imported(live);final result=await live.claim(a.id);expect(result.status=='claimed'&&result.points==10,'missing receipt');await live.claim(a.id);expect(h.calls.where((v)=>v==MiniMaxEndpoint.claim).length==1,'duplicate POST');live.dispose();});
 await check('uncertain claim survives restart and next day', (d)async{final h=FakeHttp()..loseClaim=true;final s=service(d,h);final a=await imported(s);expect((await s.claim(a.id)).status=='unknown','timeout not unknown');s.dispose();time=86500000;final next=service(d,h);expect((await next.claim(a.id)).status=='unknown','pending lost');expect(h.calls.where((v)=>v==MiniMaxEndpoint.claim).length==1,'retry unknown');next.dispose();time=100000;});
 await check('automatic opt-in persists and requires today eligibility', (d)async{final h=FakeHttp();final s=service(d,h);s.dispose();final live=service(d,h);final a=await imported(live);await live.automaticTick();expect(!h.calls.contains(MiniMaxEndpoint.claim),'auto default on');await live.setAutomatic(a.id,true);h.status=response(panel(today:false));await live.automaticTick();expect(!h.calls.contains(MiniMaxEndpoint.claim),'automatic backfill');h.status=response(panel());await live.automaticTick();expect(h.calls.where((e)=>e==MiniMaxEndpoint.claim).length==1,'automatic not dispatched');live.dispose();});
 await check('metadata persistence failure prevents POST', (d)async{var failSync=false;final h=FakeHttp();final s=service(d,h,sync:()async{if(failSync)throw StateError('disk');});final a=await imported(s);failSync=true;await reject(()=>s.claim(a.id),'StorageUnavailable');expect(!h.calls.contains(MiniMaxEndpoint.claim),'POST before durable intent');s.dispose();});
 await check('concurrent claims one owner', (d)async{final h=FakeHttp();final gate=Completer<void>();h.pause=(e)async{if(e==MiniMaxEndpoint.status)await gate.future;};final s=service(d,h);final a=await imported(s);final first=s.claim(a.id);await Future<void>.delayed(Duration.zero);await reject(()=>s.claim(a.id),'Busy');gate.complete();await first;expect(h.calls.where((e)=>e==MiniMaxEndpoint.claim).length==1,'parallel POST');s.dispose();});
 await check('dispose during profile verification prevents save', (d)async{final h=FakeHttp();final gate=Completer<void>();h.pause=(e)async{if(e==MiniMaxEndpoint.profile)await gate.future;};final s=service(d,h);final v=s.verifySource(read,confirmed:true).then<Object?>((value)=>value,onError:(Object error)=>error);await Future<void>.delayed(Duration.zero);s.dispose();gate.complete();final error=await v;expect(error is MiniMaxAccountError&&error.code=='Closed','late profile was not closed');});
 await check('expired import cannot verify network', (d)async{final h=FakeHttp();final s=service(d,h);await reject(()=>s.verifySource(()async=>MiniMaxCredential.parse(fixture.bytes(row:fixture.record()..['expiresAtMs']=time),sourcePath:fixture.path(MiniMaxRegion.cn),region:'cn',nowMs:time),confirmed:true));expect(h.calls.isEmpty,'expired request');s.dispose();});
 await check('real-user ID missing rejects local fallback', (d)async{final h=FakeHttp()..profile=const MiniMaxReply(200,{'data':{'userInfo':{'subject':'not-verified'}}});final s=service(d,h);await reject(()=>s.verifySource(read,confirmed:true),'InvalidResponse');s.dispose();});
 await check('HTTP claim 401 stays unknown and never retries', (d)async{final h=FakeHttp()..receipt=const MiniMaxReply(401,null);final s=service(d,h);final a=await imported(s);expect((await s.claim(a.id)).status=='unknown','401 blind success');await s.claim(a.id);expect(h.calls.where((v)=>v==MiniMaxEndpoint.claim).length==1,'401 replay');s.dispose();});
 await check('credential expires during status: no claim dispatch', (d)async{final h=FakeHttp();final s=service(d,h);final a=await imported(s);h.pause=(e)async{if(e==MiniMaxEndpoint.status)time=1000000;};await reject(()=>s.claim(a.id),'NeedsLogin');expect(!h.calls.contains(MiniMaxEndpoint.claim),'expired credential sent');time=100000;s.dispose();});
 await check('day changes after intent fsync: no stale-day claim', (d)async{final h=FakeHttp();var syncs=0;final s=service(d,h,sync:()async{syncs++;if(syncs==2)time=86500000;});final a=await imported(s);await reject(()=>s.claim(a.id));expect(!h.calls.contains(MiniMaxEndpoint.claim),'old day intent sent');time=100000;s.dispose();});
 await check('reimport preserves unresolved claim and disables automatic', (d)async{final h=FakeHttp()..loseClaim=true;final s=service(d,h);final a=await imported(s);await s.setAutomatic(a.id,true);await s.claim(a.id);final b=await imported(s);expect(b.status=='unknown'&&!b.automatic,'reimport erased claim or copied consent');await s.claim(b.id);expect(h.calls.where((e)=>e==MiniMaxEndpoint.claim).length==1,'reimport replayed');s.dispose();});
 await check('parallel verified imports cannot overwrite newer saved account', (d)async{final s=service(d,FakeHttp());final a=await s.verifySource(read,confirmed:true),b=await s.verifySource(read,confirmed:true);await s.save(a,confirmed:true);await reject(()=>s.save(b,confirmed:true),'SourceChanged');expect((await s.list()).length==1,'duplicate account');s.dispose();});
 await check('automatic opt-in restored after reopening service', (d)async{final h=FakeHttp();final s=service(d,h);final a=await imported(s);await s.setAutomatic(a.id,true);s.dispose();final next=service(d,h);await next.automaticTick();expect(h.calls.where((e)=>e==MiniMaxEndpoint.claim).length==1,'persisted auto ignored');next.dispose();});
 await check('malformed panel stops before POST', (d)async{final h=FakeHttp()..status=response({'scene':1,'days':[]});final s=service(d,h);final a=await imported(s);await reject(()=>s.claim(a.id),'InvalidResponse');expect(!h.calls.contains(MiniMaxEndpoint.claim),'invalid status dispatched');s.dispose();});
 await check('malformed receipt is unknown rather than success', (d)async{final h=FakeHttp()..receipt=response({'claim_result':1,'points':10});final s=service(d,h);final a=await imported(s);expect((await s.claim(a.id)).status=='unknown','malformed receipt success');await s.claim(a.id);expect(h.calls.where((e)=>e==MiniMaxEndpoint.claim).length==1,'invalid receipt retry');s.dispose();});
 await check('same JSON at different source home cannot change verified credential', (d)async{final s=service(d,FakeHttp());const other='/other/auth';final otherKey='com.minimax.mcode.oauth.prod.cn\u0000${base64Url.encode(sourceSha256(utf8.encode('$other\u0000mcode-public'))).replaceAll('=','')}';final raw=Uint8List.fromList(utf8.encode(jsonEncode({'schemaVersion':1,'records':{fixture.key(MiniMaxRegion.cn):fixture.record(),otherKey:fixture.record()..['accessToken']='synthetic-new'}})));var changed=false;Future<MiniMaxCredential> source()async=>MiniMaxCredential.parse(raw,sourcePath:changed?'$other/prod/cn/mcode-public/auth.json':fixture.path(MiniMaxRegion.cn),region:'cn',nowMs:time);final v=await s.verifySource(source,confirmed:true);changed=true;await reject(()=>s.save(v,confirmed:true),'SourceChanged');s.dispose();});
 await check('expiry during claim connection prevents dispatch', (d)async{final h=FakeHttp();final s=service(d,h);final a=await imported(s);h.pause=(e)async{if(e==MiniMaxEndpoint.claim)time=1000000;};expect((await s.claim(a.id)).status=='unknown','cancelled intent not unknown');expect(!h.calls.contains(MiniMaxEndpoint.claim),'expired POST dispatched');s.dispose();});
 await check('automatic completion refreshes once and isolates callback failures', (d)async{var callbacks=0;final s=MiniMaxAccounts(store:MiniMaxMetadataStore(d,syncDirectory:()async{}),readSecret:(id)async=>null,writeSecret:(id,token)async{},deleteSecret:(id)async{},onAutomaticFinished:()async{callbacks++;throw StateError('UI failure');});await s.automaticTick();expect(callbacks==1,'missing or repeated completion');await s.automaticTick();expect(callbacks==2,'callback poisoned tick');s.dispose();});
 await check('disposed automatic tick does not notify UI', (d)async{final h=FakeHttp(),gate=Completer<void>();var callbacks=0;final s=MiniMaxAccounts(store:MiniMaxMetadataStore(d,syncDirectory:()async{}),readSecret:(id)async=>secrets[id],writeSecret:(id,token)async{secrets[id]=token;},deleteSecret:(id)async{},http:h,nowMs:()=>time,onAutomaticFinished:(){callbacks++;});final a=await imported(s);await s.setAutomatic(a.id,true);h.pause=(e)async{if(e==MiniMaxEndpoint.status)await gate.future;};final tick=s.automaticTick();await Future<void>.delayed(Duration.zero);await s.automaticTick();expect(callbacks==0,'skipped overlapping tick notified');s.dispose();gate.complete();await tick;expect(callbacks==0,'disposed callback');});
 await check('claim owner serializes save and automatic changes', (d)async{final h=FakeHttp(),gate=Completer<void>();final s=service(d,h);final a=await imported(s);final next=await s.verifySource(read,confirmed:true);h.pause=(e)async{if(e==MiniMaxEndpoint.status)await gate.future;};final claiming=s.claim(a.id);await Future<void>.delayed(Duration.zero);try{await reject(()=>s.save(next,confirmed:true),'Busy');await reject(()=>s.setAutomatic(a.id,true),'Busy');}finally{gate.complete();await claiming;s.dispose();}});
 stdout.writeln('RESULT $passed passed, $failed failed');await root.delete(recursive:true);exitCode=failed==0?0:1;
}
